      14 => 
      array (
        'kind' => 'h2',
        'text' => 'Flood insurance and lake homes',
      ),
      15 => 
      array (
        'kind' => 'para',
        'text' => 'Standard homeowners policies exclude flooding, including surface water and rising lake or creek water. Flood coverage, often through the National Flood Insurance Program, covers that risk but usually has a waiting period before it starts, so it has to be in place before high water. Groundwater seepage is a gray area under many policies, so check yours carefully.',
        'links' => 
